/**
 * Single definition of the content models (plan 06/02 section 3).
 * Imported by src/content.config.ts (Astro) and by the vitest suite.
 * The Decap config (public/admin/config.yml) is generated by scripts/gen-cms-config.mjs;
 * tests/unit/cms-drift.test.ts fails if the two drift.
 */
import { z } from 'astro/zod';

export const LOCALES = ['he', 'en'] as const;
export type Locale = (typeof LOCALES)[number];

export const PAGE_SLUGS = [
  'home', 'about', 'research-index', 'community', 'infrastructure', 'partners-index',
  'news-index', 'patients', 'join', 'contact', 'login-entry',
] as const;
export const LEGAL_SLUGS = ['privacy', 'terms', 'accessibility', 'analytics'] as const;

const kebab = z.string().regex(/^[a-z0-9]+(?:-[a-z0-9]+)*$/, 'ASCII kebab-case slug');
const isoDate = z.coerce.date();

/** Image rule: alt is required unless decorative. Files live under public/uploads. */
export const imageSchema = z
  .object({
    src: z.string().regex(/^\/uploads\/[\w./-]+$/, 'must be under /uploads/'),
    alt: z.string().default(''),
    decorative: z.boolean().default(false),
    width: z.number().int().positive().optional(),
    height: z.number().int().positive().optional(),
  })
  .refine((i) => i.decorative || i.alt.trim().length > 0, { message: 'alt text is required unless decorative', path: ['alt'] });

const link = z.object({
  label: z.string().min(1),
  url: z.string().regex(/^(\/|https:\/\/|mailto:)/, 'relative, https or mailto only'),
});

/** PageBase: common front matter. `locale` is derived from the folder (he/ or en/) and checked by tests. */
export const pageBase = {
  title: z.string().min(1).max(70),
  description: z.string().min(1).max(160),
  slug: kebab,
  locale: z.enum(LOCALES).optional(),
  translation_status: z.enum(['complete', 'pending']).default('complete'),
  draft: z.boolean().default(false),
  updated: isoDate,
  og_image: imageSchema.optional(),
  noindex: z.boolean().default(false),
};

const textBlock = z.object({ title: z.string().min(1), text: z.string().min(1) });

export const pageSchema = z
  .object({
    ...pageBase,
    slug: z.enum(PAGE_SLUGS),
    /** Page content that has not been reviewed yet; shows a visible notice. */
    needs_review: z.boolean().default(false),
    intro: z.string().optional(),
    // home
    hero: z
      .object({ eyebrow: z.string().optional(), headline: z.string(), subline: z.string(), cta_primary: link, cta_secondary: link.optional() })
      .optional(),
    value_props: z.array(z.object({ icon: z.string(), title: z.string(), text: z.string() })).max(6).optional(),
    featured_partners: z.array(kebab).optional(),
    featured_news: z.array(kebab).optional(),
    login_teaser: z.string().optional(),
    // about
    mission: z.string().optional(),
    principles: z.array(textBlock).optional(),
    team: z.array(kebab).optional(),
    governance: z.string().optional(),
    milestones: z.array(z.object({ year: z.string(), text: z.string() })).optional(),
    // community
    groups: z.array(z.object({ name: z.string(), role: z.string(), bio: z.string() })).optional(),
    events: z
      .array(z.object({ title: z.string(), date: isoDate, place: z.string(), url: z.string().optional() }))
      .optional(),
    join_cta: z.string().optional(),
    // infrastructure
    layers: z.array(z.object({ icon: z.string(), title: z.string(), text: z.string() })).optional(),
    standards: z.string().optional(),
    how_it_works: z.array(textBlock).optional(),
    // patients and families
    plain_intro: z.string().optional(),
    reading_level_note: z.string().optional(),
    privacy_promise: z.string().optional(),
    faq: z.array(z.object({ q: z.string(), a: z.string() })).optional(),
    support_links: z.array(z.object({ label: z.string(), url: z.string(), org: z.string() })).optional(),
    contact_cta: z.string().optional(),
    // join / contact
    office_role_email: z.email().optional(),
    form_notice: z.string().optional(),
    consent_text: z.string().optional(),
    success_text: z.string().optional(),
    // login entry
    who_can_login: z.array(z.object({ role: z.string(), text: z.string() })).optional(),
    request_access_text: z.string().optional(),
  })
  .superRefine((p, ctx) => {
    const need: Record<string, (keyof typeof p)[]> = {
      home: ['hero', 'value_props', 'login_teaser'],
      about: ['mission', 'principles', 'governance'],
      community: ['intro', 'groups', 'join_cta'],
      infrastructure: ['intro', 'layers', 'standards', 'how_it_works'],
      patients: ['plain_intro', 'privacy_promise', 'faq', 'contact_cta'],
      join: ['intro', 'consent_text', 'success_text', 'form_notice', 'office_role_email'],
      contact: ['intro', 'consent_text', 'success_text', 'form_notice', 'office_role_email'],
      'login-entry': ['intro', 'who_can_login', 'request_access_text'],
      'research-index': ['intro'],
      'partners-index': ['intro'],
      'news-index': ['intro'],
    };
    for (const k of need[p.slug] ?? []) {
      if (p[k] === undefined) ctx.addIssue({ code: 'custom', message: `${p.slug} requires "${String(k)}"`, path: [k as string] });
    }
  });

export const newsSchema = z.object({
  ...pageBase,
  date: isoDate,
  summary: z.string().min(1).max(300),
  cover: imageSchema.optional(),
  tags: z.array(z.string()).default([]),
  author: kebab.optional(),
});

export const researchAreaSchema = z.object({
  ...pageBase,
  name: z.string().min(1),
  summary: z.string().min(1).max(300),
  order: z.number().int().default(100),
  image: imageSchema.optional(),
  related_news: z.array(kebab).default([]),
});

/** Partners: text names only. There is deliberately NO logo field (OPEN-LOGO-PERMISSION). */
export const partnerSchema = z.object({
  ...pageBase,
  name: z.string().min(1),
  country: z.string().min(1),
  url: z.url().startsWith('https://').optional(),
  summary: z.string().min(1),
  type: z.enum(['pediatric-oncology', 'research-network', 'hospital', 'university', 'other']),
  order: z.number().int().default(100),
});

export const centerSchema = z.object({
  ...pageBase,
  name: z.string().min(1),
  city: z.string().optional(),
  kind: z.enum(['hospital', 'research-center', 'biobank']),
  status: z.enum(['participating', 'planned']),
  summary: z.string().min(1),
  url: z.url().startsWith('https://').optional(),
  order: z.number().int().default(100),
});

/** People directory. Public profiles need documented consent; entries flagged `placeholder` are synthetic. */
export const personSchema = z.object({
  ...pageBase,
  name: z.string().min(1),
  role: z.string().min(1),
  affiliation: z.string().optional(),
  bio: z.string().min(1),
  research_areas: z.array(kebab).default([]),
  consent_on_file: z.boolean().default(false),
  placeholder: z.boolean().default(false),
  order: z.number().int().default(100),
}).refine((p) => p.placeholder || p.consent_on_file, {
  message: 'a real person may be published only with consent_on_file: true',
  path: ['consent_on_file'],
});

export const legalSchema = z.object({
  ...pageBase,
  slug: z.enum(LEGAL_SLUGS),
  version: z.string().min(1),
  effective_date: isoDate,
  needs_legal_review: z.boolean().default(true),
  // accessibility statement extras
  standard: z.string().optional(),
  conformance: z.string().optional(),
  known_issues: z.array(z.string()).optional(),
  contact: z.string().optional(),
  last_review: isoDate.optional(),
});

export const settingsSchema = z.object({
  site_name: z.string(),
  tagline: z.string(),
  nav: z.array(z.object({ slug: z.string(), label: z.string() })).min(1),
  footer_text: z.string(),
  social: z.array(link).default([]),
  default_og: imageSchema.optional(),
  analytics_enabled: z.boolean().default(false),
});

export const collectionSchemas = {
  pages: pageSchema,
  news: newsSchema,
  'research-areas': researchAreaSchema,
  partners: partnerSchema,
  centers: centerSchema,
  people: personSchema,
  legal: legalSchema,
  settings: settingsSchema,
} as const;
